// 可见的菜单项
visibleMenus() {
  return this.topMenus.slice(0, this.visibleNumber)
},
// 更多功能中的菜单项
moreMenus() {
  return this.topMenus.slice(this.visibleNumber)
},
// 是否有更多功能菜单
hasMoreMenus() {
  return this.topMenus.length > this.visibleNumber
},

// 根据菜单区实际可用宽度计算可见菜单数，放不下的一律收进「更多功能」
setVisibleNumber() {
  this.$nextTick(() => {
    if (!this.topNav) return
    const topNav = this.$el?.querySelector('.top-nav')
    if (!topNav) return

    const ITEM_WIDTH = 120
    const MORE_WIDTH = 120
    const totalMenus = this.topMenus.length
    const navWidth = topNav.getBoundingClientRect().width

    if (totalMenus <= 0) {
      this.visibleNumber = 0
      return
    }

    if (totalMenus * ITEM_WIDTH <= navWidth) {
      this.visibleNumber = totalMenus
    } else {
      this.visibleNumber = Math.max(0, Math.floor((navWidth - MORE_WIDTH) / ITEM_WIDTH))
    }
  })
},

