// 合并同一帧内的尺寸和菜单变更，统一检查溢出与滚动边界
scheduleNavUpdate() {
  this.$nextTick(() => {
    if (this._navUpdateFrame !== null) return
    this._navUpdateFrame = requestAnimationFrame(() => {
      this._navUpdateFrame = null
      this.updateNavOverflow()
    })
  })
},
updateNavOverflow() {
  const navScroll = this.$refs.navScroll
  if (!this.topNav || !navScroll || !this.topMenus.length) {
    this.navOverflow = false
    this.navAtStart = true
    this.navAtEnd = true
    return
  }

  this.navOverflow = navScroll.scrollWidth - navScroll.clientWidth > 2
  this.$nextTick(() => {
    const currentNavScroll = this.$refs.navScroll
    if (currentNavScroll) this.syncNavScrollEdges(currentNavScroll)
  })
},
syncNavScrollEdges(navScroll) {
  this.navAtStart = navScroll.scrollLeft <= 2
  this.navAtEnd = navScroll.scrollLeft + navScroll.clientWidth >= navScroll.scrollWidth - 2
},
handleNavScroll() {
  const navScroll = this.$refs.navScroll
  if (navScroll) this.syncNavScrollEdges(navScroll)
},
scrollNav(direction) {
  const navScroll = this.$refs.navScroll
  if (!navScroll || !this.navOverflow) return
  const step = Math.max(180, Math.round(navScroll.clientWidth * 0.6))
  navScroll.scrollBy({ left: direction * step, behavior: 'smooth' })
},
scrollActiveMenuIntoView() {
  const navScroll = this.$refs.navScroll
  const activeMenu = navScroll?.querySelector('.nav-item.active')
  if (!navScroll || !activeMenu) return

  const viewportRect = navScroll.getBoundingClientRect()
  const activeRect = activeMenu.getBoundingClientRect()
  if (activeRect.left < viewportRect.left) {
    navScroll.scrollBy({ left: activeRect.left - viewportRect.left - 12, behavior: 'smooth' })
  } else if (activeRect.right > viewportRect.right) {
    navScroll.scrollBy({ left: activeRect.right - viewportRect.right + 12, behavior: 'smooth' })
  }
},

