/* 顶部导航 */
.top-nav {
  display: flex;
  align-items: center;
  width: 100%;
  height: 100%;
  position: relative;
}

/* 主菜单 + 更多功能：左对齐成组，紧贴排列 */
.top-nav-menus {
  display: flex;
  align-items: center;
  flex: 0 1 auto;
  min-width: 0;
  max-width: 100%;
  overflow: visible;
}

/* 右侧弹性留白，空隙留给 navbar-right 一侧 */
.top-nav-spacer {
  flex: 1;
  min-width: 0;
}

/* 主菜单横向区域：超出部分直接隐藏，未完整展示的项由 JS 收入「更多功能」 */
.nav-items-scroll {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  height: 100%;
}

tool_input.new_string:
/* 顶部导航：权限菜单全量平铺，超出时通过两侧箭头横向滚动 */
.top-nav {
  display: flex;
  align-items: center;
  width: 100%;
  height: 100%;
  min-width: 0;
}

.top-nav-arrow-slot {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 32px;
  width: 32px;
  height: 100%;
}

.top-nav-arrow-slot.is-hidden {
  visibility: hidden;
}

.top-nav-arrow {
  width: 32px;
  height: 48px;
  padding: 0;
  border: 0;
  color: var(--menu-text-color, #fff);
  background: transparent;
  font-size: 18px;
  cursor: pointer;
}

.top-nav-arrow:hover:not(:disabled) {
  background-color: rgba(255, 255, 255, 0.1);
}

.top-nav-arrow:disabled {
  cursor: default;
}

/* 可滚动菜单视口，隐藏浏览器滚动条 */
.nav-items-scroll {
  flex: 1 1 auto;
  min-width: 0;
  height: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  scroll-behavior: smooth;
}

.nav-items-scroll::-webkit-scrollbar {
  display: none;
}

